// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(address caller) public {

        bool ok;
        uint64 number = 1;
        uint64 timestamp = 2;
        uint256 basefee = 3;
        bytes32 hash = bytes32(uint256(4));
        uint64 sequenceNumber = 5;
        bytes32 batcherHash = bytes32(uint256(6));
        uint256 l1FeeOverhead = 7;
        uint256 l1FeeScalar = 8;

        vm.prank(caller);
        try c.setL1BlockValues(
            number,
            timestamp,
            basefee,
            hash,
            sequenceNumber,
            batcherHash,
            l1FeeOverhead,
            l1FeeScalar
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        address stored = c.depositorAccount();

        assertTrue(ok == (caller == stored));
    }
}
